SELECT COUNT(1)
FROM mt_order
WHERE shop_id = #{shopId}
  AND order_send_time IS NOT NULL
  AND order_send_time >= #{startEpochSeconds}
  AND order_send_time < #{endEpochSeconds}

SELECT COALESCE(SUM(income), 0)
FROM mt_order
WHERE shop_id = #{shopId}
  AND status != #{canceledStatus}
  AND income IS NOT NULL
  AND order_send_time IS NOT NULL
  AND order_send_time >= #{startEpochSeconds}
  AND order_send_time < #{endEpochSeconds}

SELECT COUNT(1)
FROM mt_order
WHERE shop_id = #{shopId}
  AND status != #{canceledStatus}
  AND order_send_time IS NOT NULL
  AND order_send_time >= #{startEpochSeconds}
  AND order_send_time < #{endEpochSeconds}

SELECT DATE(FROM_UNIXTIME(order_send_time)) AS order_date,
       HOUR(FROM_UNIXTIME(order_send_time)) AS hour_bucket,
       COUNT(1) AS order_count,
       COALESCE(SUM(income), 0) AS income_amount
FROM mt_order
WHERE shop_id = #{shopId}
  AND status != #{canceledStatus}
  AND order_send_time IS NOT NULL
  AND order_send_time >= #{startEpochSeconds}
  AND order_send_time < #{endEpochSeconds}
GROUP BY DATE(FROM_UNIXTIME(order_send_time)), HOUR(FROM_UNIXTIME(order_send_time))
ORDER BY order_date ASC, hour_bucket ASC
